def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c

    # If opponent always cooperates, keep cooperating. The parent does this
    # and it is strong against ALLC.
    if op_d == 0:
        # But near the very end, exploit an always-cooperator.
        if n >= 90:
            return 'D'
        return 'C'

    # If opponent always defects, defect.
    if op_c == 0:
        return 'D'

    # Opponent's last move and recent streak.
    last = op[-1]
    run = 0
    for i in range(n - 1, -1, -1):
        if op[i] == last:
            run += 1
        else:
            break

    # Near the end, slightly more exploitative against cooperative opponents.
    remaining = 100 - n
    if remaining <= 3:
        if op_c * 4 >= n * 3:
            return 'D'
        return 'D' if last == 'D' else 'C'

    if last == 'D':
        # Opponent just defected.
        # If they are persistently defecting, keep defecting.
        if run >= 2:
            return 'D'
        if op_d * 3 > n:
            return 'D'

        # If we just defected, try one forgiveness step to avoid mutual
        # retaliation loops against reactive opponents like TFT.
        if me and me[-1] == 'D':
            # But if opponent's defection rate is high, keep punishing.
            if op_d * 2 > n:
                return 'D'
            return 'C'

        # Single defection from an otherwise cooperative opponent:
        # retaliate once.
        return 'D'

    # Opponent just cooperated.
    # If opponent has been highly cooperative, mostly cooperate, but probe
    # near the end.
    if op_c * 5 >= n * 4:
        if n >= 95 and rng.random() < 0.25:
            return 'D'
        return 'C'

    # Mixed opponent: prefer cooperation unless recent behavior is poor.
    if op_d * 2 > n:
        return 'D'

    # Tit-for-tat with slight forgiveness: copy opponent's last move, but
    # avoid getting trapped in mutual defection after an isolated defection.
    if op[-1] == 'D':
        if len(op) >= 2 and op[-2] == 'C':
            return 'C'
        return 'D'

    return 'C'
